  provider: String!
  "\`report\`, \`official\`, \`parliament\`, \`press\`, \`book\`, \`scholarly\`, \`archive\`, \`memorial\`, \`web\`, \`forum\`, \`encyclopedia\`, \`data\` ou \`video\`."
  kind: String!
  "Fiabilité : \`official\`, \`scholarly\`, \`press\`, \`local_history\`, \`association\`, \`encyclopedia\` ou \`forum\`."
  reliability: String!
  "Titre du document."
  title: String!
  "Journal, site ou éditeur."
  publisher: String
  "Auteur, s'il est indiqué."
  author: String
  "Date du document : \`AAAA\`, \`AAAA-MM\` ou \`AAAA-MM-JJ\`."
